sp_widget.client_script:
api.controller = function($scope) {

    var c = this;

    c.activeSection = 'section1';

    var parent_form = $scope.page.g_form;

    c.showSection = function(sectiontype) {

        if (sectiontype == 'section1') {
            c.activeSection = 'section1';

			//method1
            parent_form.setValue('custom_item', '1');

			//method2
            //parent_form.setDisplay('please_enter_the_manager_s_name', true);
            //parent_form.setDisplay('please_enter_the_applicant_s_name', true);
            //parent_form.setDisplay('please_chiose_laptop_type', false);
            //parent_form.setDisplay('please_enter_the_remark', false);
        } else {
            c.activeSection = 'section2';
			//method1
            parent_form.setValue('custom_item', '2');

			//method2
            //parent_form.setDisplay('please_enter_the_manager_s_name', false);
            //parent_form.setDisplay('please_enter_the_applicant_s_name', false);
            //parent_form.setDisplay('please_chiose_laptop_type', true);
            //parent_form.setDisplay('please_enter_the_remark', true);
        }

    }

}
